// 0.26.4.6: longest phrases first; single words only as whole words. Plain substring
// replacement turned "Hausklima" into "Houseklima" and "Raumübersicht" into "Roomübersicht".
export const FAIQ_EN_RULES = [...FAIQ_NATIVE_EN, ...FAIQ_UI_EN]
  .filter(([de]) => de)
  .sort((a, b) => b[0].length - a[0].length)
  .map(([de, en]) => /^[\p{L}\p{N}₂.\-]+$/u.test(de)
    ? [new RegExp(`(?<![\\p{L}\\p{N}])${de.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?![\\p{L}\\p{N}])`, "gu"), en]
    : [de, en]);
export { FAIQ_NATIVE_EN, FAIQ_UI_EN };
